1	-- Criar tabela para itens da pipeline baseados na requisição
2	CREATE TABLE public.pipeline_itens (
3	    id BIGSERIAL PRIMARY KEY,
4	    pipeline_id BIGINT NOT NULL REFERENCES public.requisition_pipelines(id) ON DELETE CASCADE,
5	    nome_produto TEXT NOT NULL,
6	    quantidade_solicitada INTEGER NOT NULL DEFAULT 0,
7	    quantidade_enviada INTEGER NOT NULL DEFAULT 0,
8	    quantidade_separada INTEGER DEFAULT 0,
9	    observacao TEXT,
10	    ordem INTEGER NOT NULL DEFAULT 0,
11	    status TEXT DEFAULT 'pendente' CHECK (status IN ('pendente', 'separando', 'separado', 'carregado', 'entregue')),
12	    created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL,
13	    updated_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL
14	);
15	
16	-- Adicionar índices para melhor performance
17	CREATE INDEX idx_pipeline_itens_pipeline_id ON public.pipeline_itens(pipeline_id);
18	CREATE INDEX idx_pipeline_itens_status ON public.pipeline_itens(status);
19	CREATE INDEX idx_pipeline_itens_ordem ON public.pipeline_itens(pipeline_id, ordem);
20	
21	-- Adicionar RLS (Row Level Security)
22	ALTER TABLE public.pipeline_itens ENABLE ROW LEVEL SECURITY;
23	
24	-- Política para permitir acesso aos usuários autenticados
25	CREATE POLICY "Usuários autenticados podem ver itens da pipeline" ON public.pipeline_itens
26	    FOR SELECT USING (auth.role() = 'authenticated');
27	
28	CREATE POLICY "Usuários autenticados podem inserir itens da pipeline" ON public.pipeline_itens
29	    FOR INSERT WITH CHECK (auth.role() = 'authenticated');
30	
31	CREATE POLICY "Usuários autenticados podem atualizar itens da pipeline" ON public.pipeline_itens
32	    FOR UPDATE USING (auth.role() = 'authenticated');
33	
34	CREATE POLICY "Usuários autenticados podem deletar itens da pipeline" ON public.pipeline_itens
35	    FOR DELETE USING (auth.role() = 'authenticated');
36	
37	-- Comentários explicativos
38	COMMENT ON TABLE public.pipeline_itens IS 'Itens da requisição associados a uma pipeline';
39	COMMENT ON COLUMN public.pipeline_itens.pipeline_id IS 'ID da pipeline à qual o item pertence';
40	COMMENT ON COLUMN public.pipeline_itens.nome_produto IS 'Nome do produto';
41	COMMENT ON COLUMN public.pipeline_itens.quantidade_solicitada IS 'Quantidade solicitada na requisição';
42	COMMENT ON COLUMN public.pipeline_itens.quantidade_enviada IS 'Quantidade que deve ser enviada';
43	COMMENT ON COLUMN public.pipeline_itens.quantidade_separada IS 'Quantidade efetivamente separada';
44	COMMENT ON COLUMN public.pipeline_itens.status IS 'Status do item na pipeline: pendente, separando, separado, carregado, entregue';
45	COMMENT ON COLUMN public.pipeline_itens.ordem IS 'Ordem do item na lista original da requisição';

